-- Rex Configuration generated by migration

rex.action{
  name  = "then_normal",
  title = "Run an action and return to normal mode",
  args  = { action = "string", args = "object?" },
  run   = function(ctx, args)
    rex.client.queue(args.action, args.args or {})
    rex.client.queue("client.mode.exit_all")
  end,
}


-- Bind KEY to an action that runs ACTION then leaves the mode. Each gets its own
-- title so the mode hint popup reads "Split Pane Down" instead of the wrapper text.
local once_n = 0
local function once(key, title, action, args)
  once_n = once_n + 1
  local name = "once_" .. once_n
  rex.action{
    name = name, title = title,
    run = function(ctx)
      rex.client.queue(action, args or {})
      rex.client.queue("client.mode.exit_all")
    end,
  }
  rex.bind(key, name)
end

